const wait = (ms, name, signal) =>
  new Promise((ok) => {
    const t = setTimeout(() => { console.log(name); ok(); }, ms);
    signal?.addEventListener("abort", () => clearTimeout(t));
  });
const fail = (ms) =>
  new Promise((_, no) => setTimeout(() => no(new Error("boom")), ms));
Promise.all([
  wait(300, "A"),
  fail(100),
  wait(200, "C"),
]).catch(() => console.log("rejected"));

const wait = (ms, name, signal) =>
  new Promise((ok) => {
    const t = setTimeout(() => { console.log(name); ok(); }, ms);
    signal?.addEventListener("abort", () => clearTimeout(t));
  });
const fail = (ms) =>
  new Promise((_, no) => setTimeout(() => no(new Error("boom")), ms));
const ac = new AbortController();
Promise.all([
  wait(300, "A", ac.signal),
  fail(100),
  wait(200, "C", ac.signal),
]).catch(() => {
  console.log("rejected");
  ac.abort();
});

Promise.allSettled([
  Promise.reject(new Error("x")),
  Promise.resolve(2),
]).then((r) => {
  console.log(r[0].status, r[1].status);
});
